import { R, type Review } from "./review-kit";

export const REVIEWS_B: Review[] = [
  R("rv-concerta-crush", "Vihaan, 8, Noida", "ADHD. He cannot swallow tablets, so his mother crushes them into honey.", ["Tab Concerta 18 mg  1-0-0, crush and mix with honey"], "A slow-release tablet must not be crushed", ["18 mg is above the dose for his age", "Honey stops methylphenidate being absorbed", "Concerta must be taken at bedtime to work"], "Concerta releases methylphenidate slowly over the day. Crushing it dumps the whole dose at once, with a stronger peak and a short effect. A liquid or a different formulation suits a child who cannot swallow tablets.", "18 mg is a usual starting dose for school-age children. Honey does not block absorption. Bedtime dosing would ruin sleep.", ["methylphenidate"], "child", 2, "formulation", "Recognise slow-release tablets that must not be crushed."),
  R("rv-ven-xr-tds", "Mrs Patel, 52, Vadodara", "Depression. The chemist dispensed the extended-release form.", ["Cap Veniz XR 75 mg  1-1-1"], "An XR capsule given three times a day", ["75 mg capsules do not exist", "Venlafaxine is not an antidepressant", "Venlafaxine must be crushed for older adults"], "Extended-release venlafaxine is designed for once-daily dosing. Taking it three times a day gives 225 mg spread oddly, more side effects and confusion about the dose. The plain tablet is given twice daily; the XR once.", "75 mg XR capsules exist. Venlafaxine is an SNRI antidepressant. Extended-release capsules must be swallowed whole, not crushed.", ["venlafaxine"], "antidepressants", 2, "formulation", "Match dosing frequency to the formulation."),
  R("rv-bpn-swallow", "Mr Chanu, 34, Imphal", "Starting opioid substitution.", ["Tab Addnok 2 mg  swallow with water, 1-0-0"], "It must go under the tongue", ["2 mg is above the maximum", "Buprenorphine treats only alcohol", "It must be taken at night"], "Swallowed buprenorphine is mostly destroyed by the liver before it reaches the blood, so it barely works. It is placed under the tongue until it dissolves.", "Daily doses go well above 2 mg. It treats opioid dependence. Timing of day is flexible.", ["buprenorphine"], "substance", 1, "route", "Recall that buprenorphine is taken under the tongue."),
  R("rv-li-plain-sr", "Mr Joseph, 47, Kottayam", "Stable on Licab 300 mg three tablets at night with a level of 0.7. The chemist ran out and gave a slow-release brand instead.", ["Tab Lithosun SR 450 mg  0-0-2 (substituted)", "No lithium level planned"], "Switching lithium brands needs a level check", ["Lithium is only sold as one brand", "Slow-release lithium cannot be taken at night", "A level of 0.7 is toxic"], "Lithium preparations differ in how they are absorbed, and here the total dose changed too (900 mg to 900 mg, but a different release). Brands should not be swapped without a reason, and a switch needs a level check.", "There are several lithium brands. Slow-release lithium is often taken at night. 0.7 is within range.", ["lithium"], "stabilisers", 3, "brand switch", "Check a level when the lithium preparation changes."),
  R("rv-clz-restart", "Mr Rao, 38, Guntur", "Stopped clozapine 300 mg four days ago after a family trip. Wants to restart.", ["Tab Sizopin 100 mg  1-0-2, restart today at the same dose"], "Must be built up again from low", ["Clozapine can never be restarted", "300 mg is above the maximum", "Clozapine must be restarted as an injection"], "Tolerance to clozapine's effects on blood pressure and the heart is lost quickly. After a gap of more than about two days, it is restarted at 12.5 mg and built up again, with monitoring.", "Clozapine can be restarted, slowly. 300 mg is within range. There is no injection form in routine use.", ["clozapine"], "antipsychotics", 4, "restarting clozapine", "Re-titrate clozapine after a gap."),
  R("rv-depot-test", "Mr Bhagat, 41, Ranchi", "Never had an antipsychotic before. Poor adherence feared by the family.", ["Inj Fluanxol Depot 40 mg IM today, then every 14 days"], "No oral or test dose first", ["Flupentixol is not an antipsychotic", "Depots are never used in schizophrenia", "Injections must be given into a vein"], "Depot injections last for many days and cannot be removed. Tolerability is checked first with oral medicine or a small test dose, so a reaction is not locked in for a long time.", "Flupentixol is an antipsychotic. Depots are widely used in schizophrenia. They are given into a muscle.", ["flupentixol"], "antipsychotics", 3, "depot", "Check tolerability before a first depot."),
  R("rv-ser-child-ocd-ok", "Meher, 13, Chandigarh", "OCD with contamination fears, in CBT with exposure work.", ["Tab Zosert 25 mg  1-0-0, increase to 50 mg after review", "Review in 14 days with parents"], "No clear problem: a careful plan", ["Sertraline is never used in children", "25 mg tablets do not exist", "OCD is not treated with SSRIs"], "Sertraline is licensed for OCD in children, started low with CBT, and reviewed early with the family. This is sound.", "Sertraline is used in children with OCD. 25 mg tablets exist. SSRIs are a main medicine for OCD.", ["sertraline"], "antidepressants", 2, "a sound prescription", "Recognise a sound prescription for a child."),
  R("rv-ris-child-nobloods", "Kabir, 12, Bengaluru", "Autism with severe irritability and aggression. Behaviour support in place.", ["Tab Risdone 0.5 mg  0-0-1", "Weight, waist, prolactin, sugar: not planned"], "No weight, sugar or prolactin checks", ["Risperidone is never used in autism", "0.5 mg is far above the child dose", "Risperidone must be given by injection"], "Risperidone is used for severe irritability in autism, but children gain weight quickly and prolactin rises. Baseline and regular weight, height, waist, sugar, lipids and prolactin checks are needed.", "Risperidone is used for irritability in autism. 0.5 mg is a low dose. It is given by mouth.", ["risperidone"], "child", 3, "metabolic monitoring", "Plan metabolic and prolactin checks in children on risperidone."),
  R("rv-atx-noliver", "Ishita, 16, Lucknow", "ADHD on atomoxetine. New dark urine, yellow eyes and tummy pain.", ["Cap Axepta 40 mg  1-0-0 (continue)", "Advice: carry on"], "Possible liver injury: urgent tests", ["Atomoxetine always turns urine dark", "40 mg is a dangerous dose", "Atomoxetine is a stimulant"], "Atomoxetine can rarely cause serious liver injury. Jaundice, dark urine or abdominal pain mean stopping and checking liver function urgently.", "Dark urine is not a normal effect. 40 mg is within range. Atomoxetine is a non-stimulant.", ["atomoxetine"], "child", 4, "liver warning signs", "Act on liver warning signs on atomoxetine."),
  R("rv-mph-holiday", "Dhruv, 11, Jaipur", "ADHD on methylphenidate, now in the summer holidays. Height is falling behind.", ["Tab Inspiral 10 mg  1-1-0, every day including holidays"], "A holiday break could help growth", ["Methylphenidate must be doubled in holidays", "His height has nothing to do with the medicine", "Inspiral is not methylphenidate"], "Stimulants can slow growth a little. When height falls behind, planned breaks in holidays, with the family, are one option, along with dose review and good nutrition.", "There is no reason to double the dose. Growth slowing is a known stimulant effect. Inspiral is a methylphenidate brand.", ["methylphenidate"], "child", 3, "growth", "Discuss drug holidays when growth slows."),
  R("rv-mel-child-ok", "Aarohi, 7, Ahmedabad", "Autism with sleep onset after 11 pm despite a good routine.", ["Tab Meloset 2 mg  30 minutes before bed", "Keep bedtime routine; review in 30 days"], "No clear problem: a reasonable plan", ["Melatonin is never given to children", "2 mg is above any child dose", "Melatonin must be given in the morning"], "Low-dose melatonin before bed is used for sleep onset problems in autism once routines are in place, with review.", "Melatonin is used in children for this. 2 mg is a common dose. Morning melatonin would shift the clock the wrong way.", ["melatonin"], "child", 1, "a sound prescription", "Recognise a reasonable melatonin plan."),
  R("rv-imi-child", "Ishaan, 9, Indore", "Bedwetting. No alarm or desmopressin tried.", ["Tab Depsonil 25 mg  0-0-1", "Supply: 90 tablets"], "Alarm first; big tricyclic supply", ["Imipramine never helps bedwetting", "25 mg is above the adult dose", "Depsonil must be taken in the morning"], "Imipramine can reduce bedwetting but is second-line because of side effects and danger in overdose, especially to young siblings. A bedwetting alarm and desmopressin come first, and large supplies are avoided.", "Imipramine does reduce bedwetting. 25 mg is a small adult dose. Night dosing suits bedwetting.", ["imipramine"], "child", 3, "child safety", "Use tricyclics in children only after first-line steps, with small supplies."),
  R("rv-esc-teen-ok", "Nidhi, 17, Mumbai", "Depression; tried fluoxetine without benefit. Therapy ongoing.", ["Tab Nexito 5 mg  1-0-0, review in 7 days", "Family told warning signs"], "No clear problem here", ["Escitalopram is banned under 18", "5 mg is a dangerous dose", "Reviews should wait three months"], "Escitalopram is a recognised second-line choice in adolescent depression after fluoxetine, started low with early review and the family aware of warning signs.", "It is used in older adolescents. 5 mg is a low start. Early review is good practice.", ["escitalopram"], "antidepressants", 2, "a sound prescription", "Recognise a careful adolescent prescription."),
  R("rv-ser-bf-ok", "Mrs Ansari, 30, Hyderabad", "Postnatal depression, breastfeeding a healthy full-term baby.", ["Tab Daxid 50 mg  1-0-0", "Watch baby's feeding and sleep"], "No clear problem: fine to breastfeed", ["All antidepressants must stop breastfeeding", "Sertraline passes into milk at toxic levels", "50 mg is too high to start"], "Sertraline passes into breast milk in very low amounts and is a common choice when breastfeeding. Watching the baby's feeding and sleep is sensible.", "Breastfeeding usually continues on sertraline. Milk levels are very low. 50 mg is the usual start.", ["sertraline"], "antidepressants", 2, "breastfeeding", "Choose an antidepressant compatible with breastfeeding."),
  R("rv-li-bf", "Mrs Bose, 29, Kolkata", "Bipolar disorder; delivered a premature baby and wants to breastfeed.", ["Tab Licab 300 mg  0-0-3 (continue)", "Breastfeed fully; no baby checks planned"], "Premature baby: needs specialist plan", ["Lithium cannot be taken after delivery", "300 mg tablets do not exist", "Lithium is safe at any level for babies"], "Lithium passes into breast milk, and premature babies clear it poorly. Breastfeeding on lithium is often advised against or done only with specialist support and baby blood tests.", "Lithium after delivery helps prevent postpartum relapse. 300 mg tablets exist. Lithium is never safe at any level.", ["lithium"], "stabilisers", 4, "breastfeeding", "Plan specialist care for lithium in breastfeeding."),
  R("rv-vpa-preg-folate", "Mrs Thakur, 27, Shimla", "Epilepsy and bipolar disorder on valproate for years. Just found she is pregnant; the plan is to continue.", ["Tab Encorate Chrono 500 mg  1-0-1 (continue)", "No specialist referral, no folic acid"], "Needs urgent specialist review", ["Valproate is the safest medicine in pregnancy", "Encorate is not valproate", "Valproate only matters in the last month"], "Valproate carries a high risk of birth defects and learning problems. A pregnant woman on it needs urgent specialist review of the safest options (stopping suddenly may risk fits), high-dose folic acid and pregnancy scans.", "Valproate is among the riskiest medicines in pregnancy. Encorate is a valproate brand. The highest risk is in early pregnancy.", ["valproate"], "stabilisers", 5, "valproate in pregnancy", "Act urgently when a woman on valproate becomes pregnant."),
  R("rv-cbz-preg", "Mrs Das, 33, Guwahati", "Bipolar disorder on carbamazepine; planning a pregnancy next year.", ["Tab Tegretol CR 400 mg  1-0-1 (continue)", "Pre-pregnancy advice: none"], "No pre-pregnancy planning", ["Carbamazepine has no pregnancy risks", "Carbamazepine improves fertility", "400 mg tablets do not exist"], "Carbamazepine raises the risk of birth defects, makes the pill unreliable and needs folic acid. Planning a pregnancy is the time to review the medicine and start folic acid.", "Carbamazepine does carry pregnancy risks. It does not improve fertility. 400 mg CR tablets exist.", ["carbamazepine"], "stabilisers", 3, "pre-pregnancy planning", "Plan ahead for pregnancy on carbamazepine."),
  R("rv-ltg-preg-ok", "Mrs Iyer, 32, Bengaluru", "Bipolar depression prevention; pregnant, stable on lamotrigine.", ["Tab Lamitor 100 mg  1-0-1 (continue)", "Folic acid; lamotrigine levels and mood checked during pregnancy"], "No clear problem: well planned", ["Lamotrigine must be stopped at once", "Folic acid is harmful with lamotrigine", "Lamotrigine levels rise sharply in pregnancy"], "Lamotrigine is among the safer mood stabilisers in pregnancy. Levels usually fall in pregnancy, so checks help, along with folic acid.", "Stopping suddenly risks relapse. Folic acid is recommended. Levels tend to fall, not rise, in pregnancy.", ["lamotrigine"], "stabilisers", 4, "a sound prescription", "Recognise a sound mood stabiliser plan in pregnancy."),
  R("rv-pro-preg", "Mrs Kaur, 28, Amritsar", "Thirty days before her due date. Anxious about labour.", ["Tab Ciplar 40 mg  1-0-1"], "Risks to the baby's growth and heart", ["Propranolol is a benzodiazepine", "40 mg tablets do not exist", "Propranolol makes labour start early"], "Beta-blockers in pregnancy, especially regular higher doses, are linked to slower growth and, near delivery, a slow heart rate and low sugar in the newborn. Non-drug help or obstetric advice comes first.", "Propranolol is a beta-blocker. 40 mg tablets exist. It does not start labour.", ["propranolol"], "anxiety", 4, "pregnancy", "Recognise beta-blocker risks late in pregnancy."),
  R("rv-benzo-preg", "Mrs Shaikh, 26, Mumbai", "Panic attacks; due to deliver soon.", ["Tab Alprax 1 mg  1-1-1, long-term"], "Newborn may be floppy and withdraw", ["Alprazolam treats panic only in men", "1 mg tablets do not exist", "Alprazolam speeds up labour"], "Regular benzodiazepines late in pregnancy can cause a floppy, sleepy newborn and withdrawal after birth. Panic is better treated with therapy and, if needed, an SSRI, with obstetric and paediatric planning.", "Alprazolam works in both sexes. 1 mg tablets exist. It does not speed labour.", ["alprazolam"], "anxiety", 3, "pregnancy", "Recognise benzodiazepine risks near delivery."),
  R("rv-pgb-misuse-repeat", "Mr Dhillon, 24, Bathinda", "Comes to a new doctor every few days asking for pregabalin.", ["Cap Pregeb 300 mg  1-0-1", "Repeat as requested"], "A pattern that suggests misuse", ["Pregabalin cannot be given to men", "300 mg capsules do not exist", "Pregabalin must be injected"], "Frequent early requests from different doctors suggest misuse. A careful history, checking for opioid use and a plan with controlled supplies are needed.", "Pregabalin is used in both sexes. 300 mg capsules exist. It is taken by mouth.", ["pregabalin"], "substance", 3, "misuse pattern", "Spot a pattern of prescription misuse."),
  R("rv-thx-young", "Mr Kumar, 22, Agra", "On risperidone 2 mg, no stiffness or tremor. Asks for more trihexyphenidyl every visit.", ["Tab Risdone 2 mg  0-0-1 (continue)", "Tab Trihexy 2 mg  1-1-1"], "No stiffness: likely misuse", ["Risperidone 2 mg is above the maximum", "Trihexyphenidyl prevents tardive dyskinesia", "Trihexy is not trihexyphenidyl"], "Anticholinergics are only for actual stiffness or dystonia. Without them, they add harm, may worsen tardive dyskinesia and are misused for a high.", "2 mg risperidone is a usual dose. Anticholinergics can worsen, not prevent, tardive dyskinesia. Trihexy is a trihexyphenidyl brand.", ["trihexyphenidyl"], "antipsychotics", 3, "anticholinergic misuse", "Question anticholinergics without movement side effects."),
  R("rv-hal-dystonia-ok", "Sahil, 19, Rohtak", "Acute dystonia after haloperidol: eyes rolled up, neck twisted.", ["Inj promethazine 25 mg IM now", "Review haloperidol dose and choice"], "No clear problem: right treatment", ["Dystonia needs more haloperidol", "Promethazine is an antipsychotic", "Dystonia always passes without treatment"], "An anticholinergic or antihistamine injection relieves acute dystonia within minutes, and the antipsychotic is reviewed. This is a sound plan.", "More haloperidol would worsen it. Promethazine is an antihistamine with anticholinergic action. Untreated dystonia is painful and frightening.", ["haloperidol"], "antipsychotics", 3, "a sound prescription", "Recognise sound treatment of acute dystonia."),
  R("rv-ari-akath", "Mr Shetty, 40, Mangaluru", "On aripiprazole 30 mg; paces all day, says he wants to jump out of his skin. Mentions dark thoughts.", ["Tab Aripra 30 mg  1-0-0 (continue)", "Tab Pacitane 2 mg  1-0-1 added for restlessness"], "Akathisia: lower dose, add propranolol", ["Aripiprazole never causes restlessness", "30 mg is above the maximum", "Pacitane is the first choice for akathisia"], "Severe akathisia raises suicide risk and needs prompt action: lower the aripiprazole dose, consider propranolol, ask about the dark thoughts. Anticholinergics are not effective for akathisia.", "Aripiprazole commonly causes akathisia. 30 mg is the maximum, not above it. Anticholinergics work for stiffness, not akathisia.", ["aripiprazole", "propranolol"], "antipsychotics", 4, "akathisia", "Treat akathisia correctly and ask about suicide."),
  R("rv-nms", "Mr Ali, 28, Bhopal", "Two days after haloperidol injections: fever 39.5, rigid all over, confused, sweating, CK very high.", ["Inj Serenace 10 mg IM twice daily (continue)", "Inj paracetamol for fever"], "Possible NMS: stop it, emergency care", ["This is just a viral fever", "The dose of haloperidol is too low", "Paracetamol alone will fix this"], "Fever, rigidity, confusion, unstable vital signs and a high CK after an antipsychotic point to neuroleptic malignant syndrome, an emergency. The antipsychotic stops at once and medical care follows.", "A viral fever does not cause lead-pipe rigidity with a very high CK. More haloperidol would be dangerous. Paracetamol does not treat the cause.", ["haloperidol"], "antipsychotics", 4, "neuroleptic malignant syndrome", "Recognise neuroleptic malignant syndrome and stop the cause."),
  R("rv-ss-toxic", "Ms Wadhwa, 27, Gurugram", "On sertraline; started tramadol yesterday. Now agitated, sweating, temperature 38.8, legs jerk when tapped.", ["Tab Serta 100 mg  1-0-0 (continue)", "Tab Tramazac 50 mg  1-1-1 (continue)", "Tab paracetamol for fever"], "Likely serotonin syndrome", ["This is neuroleptic malignant syndrome", "Sertraline should be doubled", "Tramadol lowers serotonin"], "Agitation, sweating, fever and inducible clonus after adding tramadol to an SSRI point to serotonin syndrome. Both stop and medical care follows.", "NMS follows antipsychotics and causes slow-onset rigidity rather than jerking reflexes. Doubling sertraline would worsen it. Tramadol raises serotonin.", ["sertraline"], "antidepressants", 4, "serotonin syndrome", "Tell serotonin syndrome from neuroleptic malignant syndrome."),
  R("rv-li-toxic", "Mrs Nair, 63, Kozhikode", "On lithium; vomiting, coarse tremor, unsteady, confused. Started a thiazide recently.", ["Tab Intalith CR 450 mg  0-0-1 (continue)", "Tab Aquazide 25 mg  1-0-0 (continue)", "Syrup for vomiting"], "Probable lithium toxicity", ["She just needs a stronger anti-sickness syrup", "Lithium should be increased", "Thiazides lower lithium, so it is not toxicity"], "Coarse tremor, vomiting, unsteadiness and confusion on lithium, after a thiazide, suggest toxicity. Hold lithium, check the level, kidney function and salts urgently.", "Treating the vomiting alone misses toxicity. Increasing lithium is dangerous. Thiazides raise lithium.", ["lithium"], "stabilisers", 4, "lithium toxicity", "Recognise lithium toxicity and act."),
  R("rv-clz-fever", "Mr Hegde, 29, Udupi", "Day 18 of clozapine: fever, sore throat, mouth ulcers.", ["Tab Lozapin 100 mg  1-0-1 (continue)", "Tab azithromycin for throat infection"], "Urgent blood count first", ["Clozapine always causes throat infections", "Azithromycin cures agranulocytosis", "The clozapine dose is too low"], "Fever and sore throat early in clozapine treatment can mean agranulocytosis. An urgent full blood count comes first, and clozapine is stopped if white cells are low.", "Infection is not a routine clozapine effect; low white cells must be ruled out. Antibiotics do not restore white cells. The dose is not the issue.", ["clozapine"], "antipsychotics", 3, "clozapine fever", "Act on fever and sore throat on clozapine."),
  R("rv-clz-myo", "Mr Prakash, 33, Coimbatore", "Fifteen days into clozapine. Chest pain, breathless, pulse 130, fever.", ["Tab Sizopin 100 mg  1-0-2 (continue)", "Advice: rest at home"], "Possible myocarditis: urgent tests", ["A fast pulse is always harmless on clozapine", "He needs a higher clozapine dose", "Chest pain is only anxiety"], "Myocarditis is an early, dangerous clozapine reaction: chest pain, breathlessness, fever and a fast pulse. Troponin, CRP and an ECG are needed urgently, and clozapine is stopped if confirmed.", "A fast pulse is common on clozapine but with chest pain and fever it needs checking. More clozapine is wrong. Anxiety is a diagnosis of exclusion here.", ["clozapine"], "antipsychotics", 5, "clozapine myocarditis", "Recognise early clozapine myocarditis."),
  R("rv-olz-lai", "Mr Pandey, 35, Varanasi", "Schizophrenia; long-acting olanzapine injection given today.", ["Inj olanzapine long-acting 300 mg IM", "Discharge home straight after"], "No observation after the injection", ["Olanzapine injections do not exist", "300 mg is far above any dose", "It must be given into a vein"], "Long-acting olanzapine can rarely cause a post-injection reaction with heavy sedation and confusion. People are observed for some hours after each dose.", "Long-acting olanzapine exists. 300 mg is a recognised dose. It is given into a muscle.", ["olanzapine"], "antipsychotics", 4, "post-injection observation", "Recall observation after long-acting olanzapine."),
  R("rv-ari-ok-prl", "Ms Ghosh, 25, Kolkata", "Periods stopped on risperidone; prolactin high. Psychosis well controlled.", ["Tab Risdone: taper and stop", "Tab Arip MT 10 mg  1-0-0", "Prolactin recheck"], "No clear problem: a sensible switch", ["Aripiprazole raises prolactin even more", "Risperidone must be stopped overnight", "Prolactin never needs rechecking"], "Switching to aripiprazole, a D2 partial agonist, often brings prolactin back to normal, with a gradual cross-taper and a recheck.", "Aripiprazole tends to lower prolactin. A taper is safer than stopping overnight. Rechecking shows whether it worked.", ["aripiprazole", "risperidone"], "antipsychotics", 3, "a sound prescription", "Recognise a sound switch for high prolactin."),
  R("rv-ecg-missing", "Mr Verma, 60, Delhi", "Heart attack last year. Psychosis now.", ["Tab Serenace 10 mg  1-0-1", "ECG: not done"], "No ECG first", ["Haloperidol cannot treat psychosis", "10 mg tablets do not exist", "Haloperidol lowers QT"], "Haloperidol lengthens QT. With heart disease, a baseline ECG and electrolytes guide the choice and dose.", "Haloperidol treats psychosis. 10 mg tablets exist. It lengthens, not shortens, QT.", ["haloperidol"], "antipsychotics", 2, "ECG before antipsychotics", "Get an ECG before antipsychotics in heart disease."),
  R("rv-que-xr-crush", "Mrs Rao, 70, Vijayawada", "Bipolar disorder; trouble swallowing after a stroke.", ["Tab Qutipin XR 300 mg  0-0-1, crush and give via feeding tube"], "XR tablets must not be crushed", ["Quetiapine cannot be used after a stroke", "300 mg is above the maximum", "XR tablets are only for children"], "Crushing an extended-release tablet releases the whole dose at once, with a sedation and blood pressure spike. Plain tablets or another formulation suit a feeding tube, with pharmacist advice.", "Quetiapine can be used with care after a stroke. 300 mg is within range. XR tablets are for adults.", ["quetiapine"], "antipsychotics", 3, "formulation", "Avoid crushing extended-release tablets."),
  R("rv-dvl-crush", "Mr Kapoor, 58, Delhi", "Depression; finds tablets hard to swallow.", ["Tab Desvenlor 50 mg  1-0-0, break in half"], "It must not be split", ["Desvenlafaxine is only for anxiety", "50 mg is above the maximum", "It must be taken three times a day"], "Desvenlafaxine is an extended-release tablet. Splitting or crushing it releases the dose too fast. A different medicine or formulation is needed if he cannot swallow it whole.", "It is used for depression. 50 mg is the usual dose. It is once daily.", ["desvenlafaxine"], "antidepressants", 2, "formulation", "Recognise tablets that must be swallowed whole."),
  R("rv-ser-old-na-ok", "Mrs Menon, 77, Kochi", "Depression; on no other medicines. Sodium normal.", ["Tab Serta 25 mg  1-0-0, then 50 mg", "Sodium check in the first month"], "No clear problem: careful plan", ["Sertraline must never be used after 75", "25 mg is too high to start", "Sodium never changes on SSRIs"], "Starting low, going up slowly and checking sodium early fits an older adult on an SSRI.", "Sertraline is widely used in older adults. 25 mg is a gentle start. SSRIs can lower sodium.", ["sertraline"], "antidepressants", 1, "a sound prescription", "Recognise a sound SSRI plan in older adults."),
  R("rv-ami-heart", "Mr Shukla, 66, Kanpur", "Heart attack two months ago. Depression and poor sleep.", ["Tab Tryptomer 50 mg  0-0-1"], "Tricyclic too soon after a heart attack", ["Amitriptyline cannot be used for sleep", "50 mg tablets do not exist", "Amitriptyline must be taken in the morning"], "Tricyclics slow heart conduction, raise the pulse and are dangerous after a recent heart attack. Sertraline has the best evidence after heart attacks.", "Low-dose amitriptyline is sometimes used for sleep, but not here. 50 mg tablets exist. Night dosing suits its sedation.", ["amitriptyline", "sertraline"], "antidepressants", 3, "heart disease", "Avoid tricyclics after a recent heart attack."),
  R("rv-cit-qt-old", "Mrs Mukherjee, 72, Siliguri", "Depression; QTc 485 on her last ECG; on furosemide.", ["Tab Stalopam 20 mg  1-0-0"], "QT already long: poor choice", ["Escitalopram never affects the heart", "20 mg is too low to help", "Furosemide shortens QT"], "A QTc already near 500 ms, plus furosemide draining potassium, makes a QT-lengthening antidepressant risky. A lower-risk choice such as sertraline, with electrolytes checked, is better.", "Escitalopram does lengthen QT. 20 mg is the adult maximum and above the cap for her age. Furosemide raises QT risk through low potassium.", ["escitalopram", "sertraline"], "antidepressants", 4, "QT and age", "Choose a lower-QT antidepressant when QT is already long."),
  R("rv-bup-smoke-ok", "Mr Menon, 41, Kochi", "Wants to quit smoking. No fits, no eating disorder, no heavy drinking.", ["Tab Smoquit SR 150 mg  1-0-0 for 3 days, then 1-0-1", "Quit date set with the counsellor"], "No clear problem: a standard quit plan", ["Bupropion is not used for smoking", "150 mg is above the maximum", "Bupropion must be stopped before the quit date"], "Bupropion is started before a set quit date and continued, with counselling. Without fits, eating disorders or heavy drinking, this plan is standard.", "Bupropion helps people quit. 150 mg twice daily is usual. It continues past the quit date.", ["bupropion"], "antidepressants", 2, "a sound prescription", "Recognise a standard bupropion quit plan."),
  R("rv-ven-stop", "Ms Kaur, 34, Ludhiana", "Feels better after a year on venlafaxine 150 mg. Wants to stop.", ["Cap Veniz XR 150 mg: stop today"], "Needs a slow taper", ["Venlafaxine must be continued for life", "150 mg is above the maximum", "Stopping only matters with SSRIs"], "Venlafaxine's short half-life makes sudden stopping likely to cause dizziness, electric-shock feelings, nausea and low mood. A slow taper over a long period is planned.", "Many people can stop when well, with a taper. 150 mg is within range. Discontinuation symptoms are common with SNRIs too.", ["venlafaxine"], "antidepressants", 2, "stopping", "Taper venlafaxine rather than stopping."),
  R("rv-par-stop", "Mr Dsouza, 55, Mangaluru", "Ran out of paroxetine 40 mg three days ago; dizzy, 'electric zaps', tearful.", ["Advice: stay off it, these symptoms show it was not needed"], "Discontinuation: restart and taper", ["The symptoms prove paroxetine never worked", "Paroxetine should be doubled", "Zaps mean epilepsy has started"], "Paroxetine has a short half-life and strong discontinuation effects. Restarting the dose and tapering slowly usually settles them. They do not mean the medicine was not needed.", "Discontinuation symptoms say nothing about benefit. Doubling is not needed. Brain zaps are a known discontinuation feature, not epilepsy.", ["paroxetine"], "antidepressants", 3, "discontinuation", "Recognise SSRI discontinuation symptoms."),
  R("rv-flx-taper", "Ms Rao, 30, Hyderabad", "Well for a year on fluoxetine 20 mg. Wants to stop.", ["Cap Fludac 20 mg  1-0-0 for 7 days, then stop", "Watch for return of symptoms"], "No clear problem: short taper is fine", ["Fluoxetine must be tapered over years", "Fluoxetine causes the worst withdrawal of all", "20 mg is above the maximum"], "Fluoxetine and its active product last a long time, so it tapers itself. From 20 mg a short plan with monitoring is reasonable.", "A taper over years is not needed. Fluoxetine has the mildest discontinuation of the SSRIs. 20 mg is a usual dose.", ["fluoxetine"], "antidepressants", 4, "a sound prescription", "Recall fluoxetine's self-tapering."),
  R("rv-lor-iv-dose", "Ward 5, Pune", "A 25-year-old with severe agitation, refused oral medicine. Lorazepam to be given.", ["Inj Ativan 2 mg IM now; repeat 2 mg every 15 minutes until calm, no maximum"], "No maximum dose or monitoring", ["Lorazepam cannot be given as an injection", "2 mg is too low to use", "Lorazepam takes days to work"], "Rapid tranquillisation needs a maximum dose, gaps between doses, and monitoring of breathing, pulse, blood pressure and alertness. Repeating without limits risks dangerous sedation.", "Lorazepam can be given by injection. 2 mg is a usual dose. It acts within minutes.", ["lorazepam"], "anxiety", 4, "rapid tranquillisation", "Set limits and monitoring in rapid tranquillisation."),
  R("rv-dia-wd", "Mr Gowda, 45, Mysuru", "Alcohol withdrawal at home; lives alone, had a withdrawal fit last year.", ["Tab Calmpose 10 mg  1-1-1-1 reducing over 7 days at home", "No one to supervise"], "Needs a supervised detox", ["Diazepam does not treat withdrawal", "10 mg tablets do not exist", "A reducing course is never used"], "A history of withdrawal fits or delirium, or no one to supervise, means detox should happen in hospital or with close supervision, with thiamine.", "Diazepam treats withdrawal. 10 mg tablets exist. Reducing courses are standard.", ["diazepam"], "substance", 4, "detox setting", "Choose a safe setting for alcohol detox."),
  R("rv-chl-long", "Mr Reddy, 48, Nizamabad", "Detox finished. Still on chlordiazepoxide at the same dose months later.", ["Cap Librium 25 mg  1-1-1 (continue indefinitely)"], "Should have been tapered off", ["Chlordiazepoxide prevents relapse long term", "25 mg capsules do not exist", "Chlordiazepoxide must be injected"], "After detox, benzodiazepines are tapered off over days. Continuing them swaps one dependence for another. Relapse prevention uses naltrexone, acamprosate or disulfiram and psychological support.", "Benzodiazepines do not prevent alcohol relapse. 25 mg capsules exist. It is taken by mouth.", ["chlordiazepoxide", "acamprosate", "naltrexone"], "substance", 2, "detox length", "Keep detox benzodiazepines short."),
  R("rv-aca-ok", "Mr Kohli, 50, Delhi", "Alcohol dependence after detox; liver disease mild; kidneys normal.", ["Tab Acamprol 333 mg  2-2-2", "Counselling and family support"], "No clear problem: sound plan", ["Acamprosate causes a reaction with alcohol", "Acamprosate is only for opioids", "Acamprosate must start before detox"], "Acamprosate supports abstinence after detox, is cleared by the kidneys and suits liver disease. 666 mg three times daily for adults over 60 kg is usual.", "Acamprosate causes no reaction with alcohol. It is used for alcohol. It starts as soon as detox is complete.", ["acamprosate"], "substance", 2, "a sound prescription", "Recognise a sound relapse prevention plan."),
  R("rv-nal-surgery", "Mrs Kapoor, 45, Delhi", "On naltrexone for alcohol. Planned knee replacement in three days.", ["Tab Nodict 50 mg  1-0-0, continue through surgery"], "Pause it before the surgery", ["Naltrexone causes bleeding in surgery", "50 mg is above the usual dose", "Naltrexone must be doubled before surgery"], "Naltrexone blocks opioid painkillers. Before planned surgery it is usually stopped a few days ahead and restarted after, with the team aware.", "Naltrexone does not cause bleeding. 50 mg is usual. Doubling would worsen the block.", ["naltrexone"], "substance", 3, "surgery", "Plan naltrexone around surgery."),
  R("rv-mem-don-ok", "Mrs Menon, 80, Kochi", "Moderate Alzheimer's disease, on donepezil, normal kidneys.", ["Tab Donecept 10 mg  0-0-1 (continue)", "Tab Admenta 5 mg  1-0-0, increase slowly to 20 mg"], "No clear problem: adding memantine is standard", ["Memantine and donepezil must never be combined", "Memantine starts at 20 mg", "Donepezil 10 mg is above the maximum"], "Adding memantine to donepezil in moderate to severe Alzheimer's disease is common, with memantine built up slowly.", "They are often combined. Memantine starts at 5 mg. 10 mg donepezil is a usual dose.", ["memantine", "donepezil"], "neurocognitive", 2, "a sound prescription", "Recognise a standard dementia combination."),
  R("rv-don-vascular", "Mr Rana, 74, Shimla", "Memory loss with step-wise decline after two strokes. Scan shows vascular changes.", ["Tab Aricep 5 mg  0-0-1", "Blood pressure, sugar, cholesterol: no plan"], "Vascular risk control is missing", ["Donepezil is banned in all dementias", "5 mg is above the maximum", "Strokes never affect memory"], "In vascular dementia, controlling blood pressure, sugar, cholesterol and smoking matters most. Donepezil has limited benefit here unless Alzheimer's disease is mixed in.", "Donepezil is used in Alzheimer's and sometimes mixed dementia. 5 mg is the usual start. Strokes can cause memory loss.", ["donepezil"], "neurocognitive", 4, "vascular dementia", "Prioritise vascular risk control in vascular dementia."),
  R("rv-delirium-benzo", "Mr Gupta, 84, Meerut", "Delirium from a urine infection; agitated at night. Not drinking alcohol.", ["Tab Ativan 1 mg  0-0-1 for sleep and calm", "Urine infection: treated"], "It can worsen delirium", ["Delirium is never caused by infections", "Lorazepam must be given in the morning", "1 mg tablets do not exist"], "Benzodiazepines often worsen confusion in delirium, except in alcohol or benzodiazepine withdrawal. Treating the cause, good lighting, family presence and sleep routines come first.", "Infections commonly cause delirium. Morning dosing would not help. 1 mg tablets exist.", ["lorazepam"], "neurocognitive", 3, "delirium", "Avoid benzodiazepines in delirium from medical causes."),
  R("rv-thx-dementia", "Mrs Hussain, 74, Srinagar", "Early Alzheimer's disease; on donepezil. Mild parkinsonism from an old antipsychotic.", ["Tab Aricep 5 mg  0-0-1 (continue)", "Tab Pacitane 2 mg  1-0-1"], "It cancels donepezil", ["Donepezil causes parkinsonism", "Pacitane is a memory medicine", "5 mg is above the maximum"], "Trihexyphenidyl blocks the receptors donepezil's extra acetylcholine needs, and worsens memory. Reviewing the old antipsychotic is better.", "Donepezil does not cause parkinsonism like this. Pacitane is an anticholinergic. 5 mg is a usual dose.", ["trihexyphenidyl", "donepezil"], "neurocognitive", 3, "cancelling medicines", "Spot medicines that cancel each other."),
  R("rv-ss-switch-ok", "Mr Arora, 33, Delhi", "Switching from sertraline 100 mg to escitalopram after side effects.", ["Tab Serta: 50 mg for 5 days, then stop", "Tab Nexito 5 mg from day 3, then 10 mg"], "No clear problem: a careful cross-taper", ["Two SSRIs must never overlap even briefly", "Escitalopram must start at 20 mg", "Sertraline must be stopped a month before"], "A short cross-taper between SSRIs at moderate doses is common, watching for serotonin side effects. This is reasonable.", "A brief overlap at low doses is used. Escitalopram starts at 5 or 10 mg. A month's gap is not needed.", ["sertraline", "escitalopram"], "antidepressants", 4, "a sound prescription", "Recognise a careful SSRI switch."),
  R("rv-fluox-que-preg", "Ms Jain, 24, Indore", "Bipolar disorder, wants a baby soon. On valproate, lithium and quetiapine from three different doctors.", ["Tab Valparin 500 mg  1-0-1", "Tab Licab 300 mg  0-0-2", "Tab Qutipin 200 mg  0-0-1", "No contraception, no folic acid"], "Valproate without pregnancy prevention", ["Quetiapine is the riskiest medicine here", "Lithium must be doubled before pregnancy", "Three medicines can never be used in bipolar disorder"], "Several things need attention, but valproate in a woman planning pregnancy without prevention or folic acid carries the gravest risk to a baby. A coordinated specialist review of all three is needed.", "Quetiapine is among the less risky options. Lithium is never doubled for pregnancy. Combinations are sometimes used; the problem is valproate.", ["valproate", "lithium", "quetiapine"], "stabilisers", 5, "full case", "Pick the most urgent problem in a complex prescription."),
  R("rv-old-polypharm", "Mr Iyer, 86, Chennai", "Falls three times this month, confused at night, constipated.", ["Tab Tryptomer 25 mg  0-0-1", "Tab Pacitane 2 mg  1-0-1", "Tab Alprax 0.5 mg  0-0-1", "Tab Zolfresh 10 mg  0-0-1"], "Too many sedating medicines for him", ["Amitriptyline 25 mg is above the maximum", "Zolpidem treats constipation", "All four are needed and safe together"], "A tricyclic, an anticholinergic, a benzodiazepine and a Z-drug together explain falls, night confusion and constipation. A careful, staged reduction is needed.", "25 mg amitriptyline is within range. Zolpidem does not treat constipation. Together these four are clearly harmful at his age.", ["amitriptyline", "trihexyphenidyl", "alprazolam", "zolpidem"], "neurocognitive", 5, "full case", "Untangle harmful polypharmacy in an older adult."),
  R("rv-clz-full", "Mr Yadav, 34, Patna", "On clozapine 500 mg, smokes heavily, now admitted for pneumonia with fever. Bowels not open for four days.", ["Tab Skizoril 100 mg  2-0-3 (continue)", "Tab Ciplox 500 mg  1-0-1", "Tab Trihexy 2 mg  1-0-1", "Smoking: not allowed on ward"], "Clozapine level will climb", ["Ciprofloxacin is the only safe antibiotic with clozapine", "Trihexyphenidyl will ease his constipation", "Pneumonia lowers clozapine levels"], "Ciprofloxacin blocks CYP1A2, stopping smoking slows it, and infection raises levels too. A clozapine level, a dose reduction, another antibiotic, stopping trihexyphenidyl and treating constipation are all needed.", "Other antibiotics are safer. Trihexyphenidyl worsens constipation. Infection raises, not lowers, clozapine levels.", ["clozapine"], "antipsychotics", 5, "full case", "Combine several clozapine risks in one assessment."),
  R("rv-ssri-bleed-full", "Mrs Mathur, 72, Jaipur", "On escitalopram, aspirin and warfarin; joint pain. Black stools this morning.", ["Tab Nexito 10 mg  1-0-0", "Tab Ecosprin 75 mg  0-1-0", "Tab Warf 3 mg  0-0-1", "Tab Brufen 400 mg  1-1-1 newly added"], "Possible bleed: emergency review", ["Black stools are a usual side effect of aspirin", "The escitalopram dose is too low", "Ibuprofen protects the stomach"], "Black stools suggest a stomach bleed. An SSRI, aspirin, warfarin and now ibuprofen all add to bleeding risk. She needs emergency assessment.", "Black stools are never routine. The escitalopram dose is not the issue. Ibuprofen harms, not protects, the stomach.", ["escitalopram"], "antidepressants", 5, "full case", "Recognise a medical emergency in a prescription review."),
  R("rv-teen-full", "Arnav, 15, Delhi", "Depression with self-harm last month. Parents work long hours.", ["Cap Fludac 20 mg  1-0-0", "Tab Tryptomer 25 mg  0-0-1 for sleep", "Supply: 60 days of both", "Follow-up: in two months"], "Tricyclic, big supply, late review", ["Fluoxetine is wrong for teens", "Amitriptyline improves suicide risk", "Two months is the ideal follow-up"], "Fluoxetine is right, but amitriptyline is dangerous in overdose, the supply is large and follow-up is too late after recent self-harm. Small supplies held by parents, no tricyclic and early review are needed.", "Fluoxetine is the first choice in teens. Amitriptyline raises overdose danger. Early review is needed.", ["fluoxetine", "amitriptyline"], "antidepressants", 5, "full case", "Make a prescription safe for a young person who self-harms."),
  R("rv-li-full", "Mr Thomas, 45, Kochi", "On lithium. Started enalapril last month and ibuprofen three days ago. Diarrhoea for two days. Level not checked for a year.", ["Tab Licab 300 mg  1-0-2", "Tab Envas 5 mg  1-0-0", "Tab Brufen 400 mg  1-1-1"], "Three things raise lithium; no level", ["Enalapril lowers lithium levels", "Diarrhoea has no effect on lithium", "Lithium must be taken only in the morning"], "Enalapril, ibuprofen and fluid loss from diarrhoea all raise lithium, and it has not been checked for a year. An urgent level, kidney tests and stopping ibuprofen are needed.", "Enalapril raises lithium. Diarrhoea dehydrates and raises it too. Lithium timing is flexible.", ["lithium"], "stabilisers", 5, "full case", "Spot several lithium risks in one prescription."),
  R("rv-opioid-full", "Mr Laldinpuia, 29, Aizawl", "On buprenorphine; injected pregabalin and drank last night. Hard to wake this morning, breathing slowly.", ["Tab Addnok 12 mg  1-0-0 (continue)", "Cap Pregeb 300 mg  1-0-1 (continue)", "Advice: sleep it off"], "An overdose emergency", ["This is opioid withdrawal", "The buprenorphine dose is too low", "Pregabalin reverses opioid effects"], "Buprenorphine with pregabalin and alcohol can stop breathing. A person who is hard to wake with slow breathing needs emergency care, airway support and naloxone where available.", "Withdrawal causes agitation and yawning, not slowed breathing. The dose is not the problem. Pregabalin adds to, not reverses, sedation.", ["buprenorphine", "pregabalin"], "substance", 5, "full case", "Recognise a sedative overdose emergency."),
  R("rv-dementia-full", "Mrs Chatterjee, 84, Siliguri", "Alzheimer's disease, sudden worse confusion, urine smells strong, agitated at night.", ["Tab Sizodon 1 mg  1-0-1 started for agitation", "Tab Donecept 10 mg  0-0-1 (continue)", "Urine test: not done"], "Look for delirium first", ["Donepezil causes urine infections", "Risperidone 1 mg is the lowest strength", "Sudden confusion is just dementia progressing"], "A sudden change in confusion in dementia suggests delirium, often from infection. The cause is found and treated first; an antipsychotic is a last resort at the lowest dose.", "Donepezil does not cause urine infections. Lower strengths exist. Dementia progresses slowly, not suddenly.", ["risperidone", "donepezil"], "neurocognitive", 5, "full case", "Tell delirium from dementia progression in a prescription review."),
  R("rv-ocd-full", "Mr Joseph, 29, Kottayam", "OCD partly better on fluvoxamine 300 mg. Now clozapine is planned for psychosis, and he smokes.", ["Tab Uvox 100 mg  1-0-2 (continue)", "Tab Lozapin 25 mg  increase to 400 mg"], "Fluvoxamine pushes clozapine up", ["Clozapine helps OCD in everyone", "Fluvoxamine lowers clozapine", "Smoking raises clozapine levels"], "Fluvoxamine strongly blocks CYP1A2, clozapine's main enzyme, so levels can rise many-fold. If both are used, clozapine needs much lower doses and level checks. Clozapine can also worsen obsessions in some people.", "Clozapine can worsen OCD in some. Fluvoxamine raises, not lowers, clozapine. Smoking lowers clozapine levels.", ["clozapine", "fluvoxamine"], "antipsychotics", 4, "CYP1A2 interaction", "Spot fluvoxamine beside clozapine."),
  R("rv-epilepsy-ss", "Ms Paul, 23, Shillong", "Epilepsy on carbamazepine; now depressed.", ["Tab Mazetol 400 mg  1-0-1 (continue)", "Tab Smoquit SR 150 mg  1-0-1"], "Bupropion makes fits likelier", ["Carbamazepine raises bupropion to toxic levels", "Bupropion is a sleeping pill", "150 mg is above the maximum"], "Bupropion is avoided in epilepsy because it makes fits more likely. Carbamazepine also lowers bupropion's level. Sertraline or another option is safer.", "Carbamazepine lowers, not raises, bupropion. Bupropion is activating. 150 mg twice daily is usual.", ["bupropion", "carbamazepine"], "antidepressants", 3, "epilepsy", "Avoid bupropion in epilepsy."),
  R("rv-tb-full", "Mr Patil, 40, Nagpur", "Started TB treatment with rifampicin and isoniazid. On quetiapine for bipolar disorder and buprenorphine for opioids.", ["Tab Qutipin 300 mg  0-0-1 (continue)", "Tab Addnok 8 mg  1-0-0 (continue)", "TB treatment started"], "Rifampicin lowers both", ["Isoniazid will lower both", "TB medicines have no effect on psychiatric medicines", "Rifampicin raises buprenorphine to toxic levels"], "Rifampicin is a very strong enzyme speeder. Quetiapine and buprenorphine levels fall, risking relapse and withdrawal. Doses are reviewed with the TB team.", "Isoniazid tends to slow enzymes rather than speed them. TB medicines interact a lot. Rifampicin lowers, not raises, buprenorphine.", ["quetiapine", "buprenorphine"], "substance", 5, "full case", "Plan around rifampicin in psychiatric prescriptions."),
  R("rv-hiv-full", "Mr Fernandes, 35, Mumbai", "HIV, starting a ritonavir-boosted regimen. On quetiapine 300 mg and alprazolam 1 mg.", ["Tab Seroquin 300 mg  0-0-1 (continue)", "Tab Alprax 1 mg  0-0-1 (continue)", "HIV treatment started"], "Ritonavir raises both", ["Ritonavir lowers quetiapine", "HIV medicines never interact", "Alprazolam lowers ritonavir"], "Ritonavir is a very strong CYP3A4 blocker. Quetiapine and alprazolam both build up. Quetiapine is cut sharply and alprazolam is usually avoided.", "Ritonavir raises, not lowers, quetiapine. HIV medicines interact a lot. Alprazolam does not lower ritonavir.", ["quetiapine", "alprazolam"], "antipsychotics", 5, "full case", "Plan around strong CYP3A4 blockers."),
  R("rv-normaxin", "Mrs Shah, 52, Ahmedabad", "Irritable bowel and anxiety. Already on clonazepam at night.", ["Tab Normaxin (chlordiazepoxide + clidinium + dicyclomine)  1-0-1", "Tab Lonazep 0.5 mg  0-0-1 (continue)"], "A hidden second benzodiazepine", ["Normaxin is a laxative", "Clonazepam treats irritable bowel", "Dicyclomine is a benzodiazepine"], "Normaxin contains chlordiazepoxide, a benzodiazepine, with two anticholinergics. With clonazepam she gets two benzodiazepines plus anticholinergic load. Combination brands should be read in full.", "Normaxin is an antispasmodic combination, not a laxative. Clonazepam is not an irritable bowel treatment. Dicyclomine is an anticholinergic antispasmodic, not a benzodiazepine.", ["chlordiazepoxide", "clonazepam"], "anxiety", 3, "hidden benzodiazepine", "Spot a benzodiazepine hidden in a gut medicine."),
  R("rv-pgb-nt", "Mr Chopra, 62, Amritsar", "Diabetic nerve pain. Already on duloxetine for depression.", ["Tab pregabalin 75 mg + nortriptyline 10 mg combination  0-0-1", "Cap Duzela 60 mg  1-0-0 (continue)"], "A hidden tricyclic with duloxetine", ["Pregabalin is a tricyclic", "Duloxetine does not treat nerve pain", "75 mg pregabalin is above the maximum"], "Many Indian nerve-pain brands combine pregabalin with nortriptyline, a tricyclic. With duloxetine that adds serotonin and noradrenaline effects, falls and heart risk in an older man.", "Pregabalin is a gabapentinoid, not a tricyclic. Duloxetine does treat nerve pain. 75 mg is a usual dose.", ["pregabalin", "duloxetine"], "antidepressants", 4, "hidden tricyclic", "Spot a tricyclic hidden in a nerve-pain combination."),
  R("rv-oleanz-bipolar-ok", "Mr Jain, 38, Indore", "Bipolar depression; normal weight; baseline metabolic tests done.", ["Tab Oleanz Plus (olanzapine 5 mg + fluoxetine 20 mg)  0-0-1", "Weight and sugar at review"], "No clear problem: well monitored", ["Fluoxetine alone is better in bipolar depression", "This combination contains lithium", "Olanzapine needs no monitoring"], "Olanzapine with fluoxetine is an established bipolar depression treatment, and the monitoring plan is in place.", "Antidepressants alone are risky in bipolar depression. There is no lithium in it. Olanzapine needs metabolic checks, which are planned.", ["olanzapine", "fluoxetine"], "antipsychotics", 3, "a sound prescription", "Recognise an evidence-based combination brand used well."),
  R("rv-tfp-nolabel", "Mr Khan, 37, Aligarh", "Told he is on 'one calming tablet'. The strip says Trinicalm Plus.", ["Tab Trinicalm Plus  1-0-1", "Patient not told it contains two medicines"], "He was not told what it is", ["Trinicalm Plus contains clonazepam", "Trinicalm Plus is a sleeping tablet only", "It must be taken once a month"], "Trinicalm Plus contains trifluoperazine, an antipsychotic, and trihexyphenidyl, an anticholinergic. He has a right to know what he takes and why, and it matters for any future prescriber.", "It contains no clonazepam. It is not just a sleeping tablet. It is a twice-daily medicine.", ["trifluoperazine", "trihexyphenidyl"], "antipsychotics", 2, "informed consent", "Explain what a combination tablet contains."),
  R("rv-bpn-n-ok", "Mr Chanu, 34, Imphal", "Opioid dependence, stable, working. Wants to take doses home.", ["Tab Addnok-N 8 mg (buprenorphine + naloxone)  sublingual 1-0-0", "Take-home supply for 7 days after review"], "No clear problem: suits take-home", ["Naloxone makes the tablet work better under the tongue", "Take-home doses are never allowed", "8 mg is above the maximum"], "The buprenorphine with naloxone combination discourages injecting, so it is often used for take-home supplies in stable patients.", "Naloxone is barely absorbed under the tongue; it is there to deter injecting. Take-home doses are used for stable patients. 8 mg is within range.", ["buprenorphine"], "substance", 3, "a sound prescription", "Recognise why the naloxone combination is used."),
  R("rv-lith-ok", "Ms Gupta, 30, Jaipur", "Bipolar disorder, stable. Kidney and thyroid normal.", ["Tab Licab 300 mg  0-0-3 (continue)", "Level 12 hours after dose; kidney and thyroid every six months", "Small supplies while low"], "No clear problem: good monitoring", ["Lithium levels are best taken just after a dose", "Kidney tests are only needed once", "Lithium must be taken in the morning"], "Levels taken about 12 hours after the last dose, regular kidney and thyroid tests and small supplies when risk is high make a sound lithium plan.", "Levels are taken about 12 hours after a dose, not just after. Kidney tests are repeated. Night dosing is common.", ["lithium"], "stabilisers", 2, "a sound prescription", "Recognise sound lithium monitoring."),
  R("rv-li-level-time", "Mr Bhatt, 60, Vadodara", "On lithium at night. Took his dose at 9 pm.", ["Lithium level ordered for 10 pm, one hour after the dose"], "Level taken far too soon after dose", ["Lithium levels must be taken while fasting for 24 hours", "The level should be taken 3 days after the dose", "Lithium levels are taken from urine"], "A level one hour after the dose catches the peak and looks falsely high. Ranges are based on a level about 12 hours after the dose, usually the next morning.", "No 24-hour fast is needed. Three days after would be too late. Levels are measured in blood.", ["lithium"], "stabilisers", 2, "level timing", "Time lithium levels correctly."),
  R("rv-vpa-lft", "Mrs Iqbal, 36, Bhopal", "Starting valproate for mania. Mild liver disease from fatty liver.", ["Tab Valparin 500 mg  0-0-1, increase to 1-0-1", "Liver tests and platelets: not planned"], "No liver or platelet tests", ["Valproate protects the liver", "500 mg is a dangerous start", "Valproate is only for epilepsy"], "Valproate can harm the liver and lower platelets. Baseline liver tests and a blood count, then checks early on, are needed, especially with existing liver disease.", "Valproate can harm the liver. 500 mg is a usual start. It is used for mania too.", ["valproate"], "stabilisers", 2, "valproate monitoring", "Recall liver and platelet checks for valproate."),
  R("rv-cbz-sodium-old", "Mrs D'Silva, 70, Pune", "Bipolar disorder; on a water tablet. Starting carbamazepine.", ["Tab Tegretol 200 mg  0-0-1, increase to 1-0-1", "Blood count and sodium: not planned"], "No sodium or blood count checks", ["Carbamazepine raises sodium", "200 mg is the maximum", "Carbamazepine needs no blood tests"], "Carbamazepine can lower sodium (more with water tablets and age) and rarely white cells. Baseline and early checks of sodium, blood count and liver tests are needed.", "It lowers, not raises, sodium. 200 mg is a starting dose; usual doses are higher. Blood tests are needed.", ["carbamazepine"], "stabilisers", 3, "carbamazepine monitoring", "Recall sodium and blood count checks on carbamazepine."),
  R("rv-ap-prl", "Ms Thakur, 26, Shimla", "On amisulpride; periods stopped, milk from breasts. Pregnancy test negative.", ["Tab Amipride 400 mg  1-0-1 (continue)", "Advice: nothing to worry about"], "Prolactin needs testing", ["Amisulpride lowers prolactin", "This proves she is pregnant", "400 mg is above the maximum"], "Missed periods and milk on amisulpride point to raised prolactin, which also harms bones and fertility. A prolactin test and dose review or switch are needed.", "Amisulpride raises prolactin strongly. The pregnancy test is negative. 800 mg a day is within the range.", ["amisulpride", "aripiprazole"], "antipsychotics", 2, "prolactin", "Act on raised prolactin symptoms."),
  R("rv-depot-eps", "Mr Yadav, 64, Patna", "Twenty years on haloperidol depot; tongue writhing and lip smacking.", ["Inj haloperidol decanoate 100 mg every 28 days (continue)", "Tab Pacitane 2 mg  1-0-1 added for the movements"], "Anticholinergic can worsen it", ["Tardive dyskinesia is cured by trihexyphenidyl", "The depot dose is too low", "Haloperidol never causes late movements"], "Tardive dyskinesia does not respond to anticholinergics, which may worsen it. Reviewing the antipsychotic, often switching to clozapine or a lower-risk drug, and specialist treatments are options.", "Anticholinergics do not cure it. The depot dose is not the issue. Long-term haloperidol is a classic cause.", ["haloperidol", "trihexyphenidyl"], "antipsychotics", 4, "tardive dyskinesia", "Manage tardive dyskinesia without anticholinergics."),
  R("rv-olz-old-dem", "Mr Murthy, 82, Mysuru", "Alzheimer's disease with mild agitation. Lives with family.", ["Tab Oleanz 10 mg  0-0-1 long-term"], "Long-term use with no review", ["Olanzapine treats Alzheimer's disease itself", "10 mg tablets do not exist", "Olanzapine must be given in the morning"], "Antipsychotics in dementia raise the risk of stroke and death. They are a last resort, at low dose, for short periods, with regular review and attempts to stop.", "Olanzapine does not treat the dementia. 10 mg tablets exist. Timing is not the issue.", ["olanzapine"], "neurocognitive", 3, "antipsychotics in dementia", "Review antipsychotics in dementia."),
  R("rv-ser-diur-old", "Mr Ghosh, 80, Howrah", "Depression; on indapamide and a low body weight.", ["Tab Zosert 50 mg  1-0-0", "Sodium: not planned"], "No early sodium check", ["Sertraline raises sodium", "50 mg is above the maximum", "Indapamide is an antidepressant"], "Older age, low weight and a thiazide-like diuretic all raise the risk of low sodium on an SSRI. A sodium check in the first month is needed.", "Sertraline can lower, not raise, sodium. 50 mg is a usual dose. Indapamide is a blood pressure tablet.", ["sertraline"], "antidepressants", 2, "sodium monitoring", "Plan sodium checks for SSRIs in older adults."),
  R("rv-mir-agranulo", "Mr Pereira, 66, Goa", "On mirtazapine; fever and sore throat for three days.", ["Tab Mirtaz 30 mg  0-0-1 (continue)", "Advice: gargle and rest"], "Needs a blood count", ["Mirtazapine always causes sore throats", "30 mg is above the maximum", "Mirtazapine must be taken in the morning"], "Mirtazapine can very rarely cause agranulocytosis. Fever, sore throat or mouth ulcers on it need a blood count.", "A sore throat is not a usual effect. The maximum is 45 mg. Night dosing is usual.", ["mirtazapine"], "antidepressants", 4, "rare blood risk", "Act on infection signs on mirtazapine."),
  R("rv-ltg-rash", "Ms Pandey, 32, Prayagraj", "Started lamotrigine 20 days ago. Rash with fever and sore mouth.", ["Tab Lamitor 50 mg  1-0-0 (continue)", "Cream for rash"], "Stop it and get urgent care", ["Lamotrigine rashes are always harmless", "The dose should be doubled", "A cream will treat it fully"], "A rash with fever, mouth sores or blistering early in lamotrigine treatment may be Stevens-Johnson syndrome. Lamotrigine is stopped and she is seen urgently.", "Some rashes are benign, but not with fever and mouth sores. Doubling would be dangerous. A cream does not treat the cause.", ["lamotrigine"], "stabilisers", 3, "serious rash", "Act on a serious rash on lamotrigine."),
  R("rv-ago-old", "Mr Ghosh, 78, Howrah", "Depression with poor sleep; dementia diagnosed last year.", ["Tab Agomelin 25 mg  0-0-1"], "Not advised in dementia", ["Agomelatine is a benzodiazepine", "25 mg is above the maximum", "Agomelatine must be taken in the morning"], "Agomelatine has limited evidence in older people and is not recommended in dementia; it also needs liver checks. Another antidepressant is a better choice.", "It is a melatonin agonist. 25 mg is the start. It is taken at bedtime.", ["agomelatine"], "antidepressants", 4, "dementia", "Choose antidepressants carefully in dementia."),
  R("rv-vor-ok", "Ms Bhatia, 40, Chandigarh", "Depression; sexual side effects on two SSRIs before.", ["Tab Vortidep 10 mg  1-0-0", "Review in 14 days"], "No clear problem here", ["Vortioxetine is an antipsychotic", "10 mg is above the maximum", "It must be taken three times a day"], "Vortioxetine is an option after SSRI sexual side effects, at a usual once-daily dose, with early review.", "It is a serotonin modulator antidepressant. The maximum is 20 mg. It is once daily.", ["vortioxetine"], "antidepressants", 1, "a sound prescription", "Recognise a reasonable antidepressant choice."),
  R("rv-trz-ok", "Mrs Qureshi, 59, Bhopal", "Depression with insomnia; no heart or prostate problems.", ["Tab Trazalon 50 mg  0-0-1", "Review in 14 days"], "No clear problem here", ["Trazodone is a stimulant", "50 mg is above the maximum", "Trazodone must be taken in the morning"], "Low-dose trazodone at night is used for sleep in depression, with review.", "It is sedating. The maximum is far higher. Night dosing suits it.", ["trazodone"], "antidepressants", 1, "a sound prescription", "Recognise a reasonable trazodone plan."),
  R("rv-bus-ok", "Mrs Arora, 63, Faridabad", "Generalised anxiety; worried about habit-forming tablets.", ["Tab Buspin 5 mg  1-1-1, increase slowly", "Explain benefit builds slowly"], "No clear problem here", ["Buspirone works within an hour", "Buspirone is a benzodiazepine", "5 mg is above the maximum"], "Buspirone suits anxious people worried about dependence, with honest advice that benefit builds slowly.", "It takes time to work. It is not a benzodiazepine. 5 mg three times daily is a usual start.", ["buspirone"], "anxiety", 1, "a sound prescription", "Recognise a sound buspirone plan."),
  R("rv-zol-long", "Ms Sethi, 45, Noida", "Insomnia for two years; on zolpidem every night; sleep-cooking episode last month.", ["Tab Nitrest 10 mg  0-0-1 (continue)", "Repeat for six months"], "Stop it: complex sleep behaviour", ["Zolpidem should be doubled", "Sleep-cooking is unrelated to zolpidem", "Nitrest is not zolpidem"], "Complex sleep behaviours such as cooking or driving while asleep are a reason to stop zolpidem. CBT for insomnia is the first treatment for long-term insomnia.", "Doubling would raise the risk. These behaviours are a known zolpidem effect. Nitrest is a zolpidem brand.", ["zolpidem"], "anxiety", 3, "complex sleep behaviour", "Act on complex sleep behaviours on zolpidem."),
  R("rv-alp-switch", "Ms Iyer, 35, Bengaluru", "Dependent on alprazolam 3 mg a day; wants to come off.", ["Tab Alprax: stop today", "No substitute, no plan"], "Sudden stop risks fits", ["Alprazolam can be stopped any time safely", "She must stay on it for life", "3 mg a day is a tiny dose"], "After long daily use, stopping suddenly risks severe withdrawal and fits. Switching to a longer-acting benzodiazepine such as diazepam and tapering slowly, with support, is safer.", "Sudden stopping is not safe. Coming off is possible with a taper. 3 mg a day is a substantial dose.", ["alprazolam", "diazepam"], "anxiety", 3, "benzodiazepine withdrawal", "Plan a safe benzodiazepine taper."),
  R("rv-pro-heart-block", "Mr Rao, 70, Guntur", "Slow pulse of 48 and dizzy spells. Anxious.", ["Tab Ciplar 20 mg  1-0-1"], "Pulse already too slow", ["Propranolol speeds the pulse", "20 mg is above the maximum", "Ciplar is an antidepressant"], "Propranolol slows the heart further. With a slow pulse and dizzy spells, it could cause fainting or heart block. A heart check and another approach to anxiety are needed.", "Propranolol slows, not speeds, the pulse. 20 mg is within range. Ciplar is a propranolol brand.", ["propranolol"], "anxiety", 2, "slow pulse", "Check the pulse before beta-blockers."),
  R("rv-mph-psych", "Mr Varma, 32, Visakhapatnam", "Adult ADHD; had a psychotic episode last year while using cannabis.", ["Cap Concerta 36 mg  1-0-0"], "Recent psychosis: review first", ["Methylphenidate prevents psychosis", "36 mg is above the adult maximum", "Concerta must be taken at night"], "Stimulants raise dopamine and can bring back psychosis. After a recent episode, careful specialist review, with non-stimulant options considered, is needed.", "Stimulants can trigger, not prevent, psychosis. 36 mg is within the adult range. Night dosing would ruin sleep.", ["methylphenidate", "atomoxetine"], "child", 4, "psychosis history", "Review psychosis history before stimulants."),
  R("rv-mph-mao", "Mr Rao, 50, Hyderabad", "Adult ADHD; also on moclobemide for depression.", ["Tab Inspiral 10 mg  1-1-0", "Tab moclobemide 150 mg  1-0-1 (continue)"], "Dangerous blood pressure rise", ["Methylphenidate lowers blood pressure", "Moclobemide is a stimulant", "10 mg is above the maximum"], "MAO inhibitors break down less noradrenaline and dopamine; adding a stimulant can push blood pressure dangerously high. The combination is avoided.", "Methylphenidate raises, not lowers, blood pressure. Moclobemide is an antidepressant. 10 mg is a usual dose.", ["methylphenidate"], "child", 5, "MAO inhibitor", "Avoid stimulants with MAO inhibitors."),
];
